package org.sleepwell.app;

import android.app.*;import android.content.*;import android.net.Uri;import android.os.*;import android.widget.TextView;import android.view.View;
import androidx.test.platform.app.InstrumentationRegistry;import androidx.test.uiautomator.*;
import org.junit.Test;import java.io.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
import static org.junit.Assert.*;

/** Explicit manual save/reopen/review through real Activities, private SQLite and fake providers. */
public final class CloudBackupFlowTest {
    private final Instrumentation i=InstrumentationRegistry.getInstrumentation();private final Context c=i.getTargetContext();private final UiDevice device=UiDevice.getInstance(i);private final List<Activity> activities=new CopyOnWriteArrayList<>();private volatile Activity current;
    private void await(java.util.function.BooleanSupplier condition)throws Exception{long end=SystemClock.elapsedRealtime()+10000;while(!condition.getAsBoolean()&&SystemClock.elapsedRealtime()<end)Thread.sleep(25);assertTrue(condition.getAsBoolean());}
    private View find(View root,String text){if(text.contentEquals(root.getContentDescription()==null?"":root.getContentDescription())||root instanceof TextView&&text.contentEquals(((TextView)root).getText()))return root;if(root instanceof android.view.ViewGroup)for(int n=0;n<((android.view.ViewGroup)root).getChildCount();n++){View found=find(((android.view.ViewGroup)root).getChildAt(n),text);if(found!=null)return found;}return null;}
    private boolean shown(String text){boolean[] yes={false};i.runOnMainSync(()->{if(current!=null&&!current.isDestroyed())yes[0]=find(current.getWindow().getDecorView(),text)!=null;});return yes[0];}
    private void click(String text)throws Exception{await(()->shown(text));i.waitForIdleSync();UiObject2 object=device.findObject(By.text(text));if(object==null)object=device.findObject(By.desc(text));assertNotNull(text,object);object.click();}
    private void capture(String name)throws Exception{i.waitForIdleSync();File folder=new File(c.getExternalFilesDir(null),"verification");assertTrue(folder.isDirectory()||folder.mkdirs());assertTrue(device.takeScreenshot(new File(folder,"cloud-backup-"+name+".png")));}
    @Test public void chooseSaveReopenAndReviewKeepLocalDataWithNoUpload()throws Exception{
        assertEquals("true",InstrumentationRegistry.getArguments().getString("ciReview"));assertEquals("1",device.executeShellCommand("getprop ro.kernel.qemu").trim());assertFalse(TrackingService.running);assertFalse(AlarmService.active);assertFalse(Prefs.flag(c,"ringing"));assertFalse(Prefs.flag(c,"tracking"));Map<String,?> personal=new HashMap<>(Prefs.of(c).getAll());
        String name="cloud-ui-"+UUID.randomUUID();SharedPreferences prefs=c.getSharedPreferences(name,0);Records.Factory oldRecords=Records.factory,records=ctx->new Store(ctx,name+".db");CloudBackupSettings.Factory oldSettings=CloudBackupSettings.factory;CloudBackupJobs.Factory oldJobs=CloudBackupJobs.factory;CloudBackupActivity.Picker oldPicker=CloudBackupActivity.picker;CloudBackupActivity.Destinations oldDestinations=CloudBackupActivity.destinations;BackupDocuments.Factory oldDocuments=BackupDocuments.factory;Map<String,byte[]> documents=new ConcurrentHashMap<>();AtomicInteger choices=new AtomicInteger(),creates=new AtomicInteger(),restores=new AtomicInteger();String original;try(Store store=records.open(c)){Alarm alarm=new Alarm(91);alarm.label="Cloud UI private alarm";store.save(alarm);original=store.backup().toString();}
        Application app=(Application)c.getApplicationContext();Application.ActivityLifecycleCallbacks lifecycle=new Application.ActivityLifecycleCallbacks(){public void onActivityCreated(Activity a,Bundle state){assertTrue(a instanceof CloudBackupActivity||a instanceof BackupActivity);activities.add(a);}public void onActivityStarted(Activity a){}public void onActivityResumed(Activity a){current=a;}public void onActivityPaused(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle state){}public void onActivityDestroyed(Activity a){}};app.registerActivityLifecycleCallbacks(lifecycle);
        try{Records.factory=records;CloudBackupSettings.factory=ctx->prefs;CloudBackupActivity.destinations=new CloudBackupActivity.Destinations(){public void choose(Context ctx,Uri tree,int flags){assertEquals("content://fixture/tree/backup",tree.toString());CloudBackupSettings.remember(prefs,tree.toString(),"Private test cloud folder",0);}public void disconnect(Context ctx){CloudBackupSettings.disconnect(prefs);}};CloudBackupActivity.picker=activity->{choices.incrementAndGet();activity.onActivityResult(CloudBackupActivity.TREE,Activity.RESULT_OK,new Intent().setData(Uri.parse("content://fixture/tree/backup")).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION));};
            CloudBackupJobs.factory=(context,pinned)->new CloudBackupJob.Work(){public CloudBackupCopy.Receipt save(java.util.function.BooleanSupplier active)throws Exception{String tree=CloudBackupSettings.destination(prefs).tree;CloudBackupCopy.Provider provider=new CloudBackupCopy.Provider(){public CloudBackupCopy.Document create(String file){creates.incrementAndGet();return new CloudBackupCopy.Document("content://fixture/tree/backup/document/"+UUID.randomUUID(),file);}public OutputStream output(CloudBackupCopy.Document doc){return new ByteArrayOutputStream(){public void close(){documents.put(doc.uri,toByteArray());}};}public InputStream input(CloudBackupCopy.Document doc){return new ByteArrayInputStream(documents.get(doc.uri));}public void cancel(){}};long now=System.currentTimeMillis();CloudBackupCopy.Receipt receipt=CloudBackupCopy.save(a->CloudBackupSnapshot.prepare(context,pinned,a),provider,"private-version.json",active,doc->CloudBackupSettings.record(prefs,new CloudBackupSettings.Entry(tree,doc.uri,doc.name,now,0,"",false)));CloudBackupSettings.record(prefs,new CloudBackupSettings.Entry(tree,receipt.document.uri,receipt.document.name,now,receipt.size,receipt.sha,true));return receipt;}public void cancel(){}};
            BackupDocuments.factory=(context,pinned)->new BackupDocuments(context,pinned,new BackupDocuments.Transport(){public InputStream input(String uri){return new ByteArrayInputStream(documents.get(uri));}public OutputStream output(String uri){throw new AssertionError("Review cannot export");}public void cancel(){}},new BackupDocuments.Effects(){public void idle(long admission){BackupRuntime.requireIdle(c,admission);}public void retired(List<Alarm> previous,Store store){restores.incrementAndGet();throw new AssertionError("Review cannot restore");}public void recover(Store store){throw new AssertionError("Review cannot remove audio");}});
            current=i.startActivitySync(new Intent(c,CloudBackupActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK).putExtra("visualReview",true));await(()->shown("Choose destination"));assertEquals(0,creates.get());click("Choose destination");await(()->shown("Private test cloud folder"));assertEquals(1,choices.get());capture("destination");click("Save a new backup");await(()->CloudBackupJobs.get(c,records).state().phase==CloudBackupJob.Phase.DONE);await(()->shown("Review"));assertEquals(1,creates.get());assertEquals(1,documents.size());assertTrue(CloudBackupSettings.history(prefs).get(0).verified);capture("saved");Activity first=current;i.runOnMainSync(first::finish);await(first::isDestroyed);current=i.startActivitySync(new Intent(c,CloudBackupActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK).putExtra("visualReview",true));await(()->shown("Private test cloud folder")&&shown("Review"));assertEquals(1,choices.get());assertEquals(1,creates.get());capture("reopened");click("Review");await(()->current instanceof BackupActivity&&shown("Review backup"));capture("restore-review");assertEquals(0,restores.get());try(Store store=records.open(c)){assertEquals(original,store.backup().toString());}click("Keep local data");await(()->BackupJobs.get(c,records).state().phase==BackupJob.Phase.CANCELLED);assertEquals(personal,Prefs.of(c).getAll());
        }finally{i.runOnMainSync(()->{for(Activity activity:activities)if(!activity.isDestroyed())activity.finish();});await(()->activities.stream().allMatch(Activity::isDestroyed));CloudBackupJobs.drain(records,8000);BackupJobs.drain(records,8000);for(Activity activity:activities)if(activity instanceof CloudBackupActivity)assertTrue(((CloudBackupActivity)activity).awaitLocal(8000));CloudBackupJobs.forget(records);BackupJobs.forget(records);app.unregisterActivityLifecycleCallbacks(lifecycle);Records.factory=oldRecords;CloudBackupSettings.factory=oldSettings;CloudBackupJobs.factory=oldJobs;CloudBackupActivity.picker=oldPicker;CloudBackupActivity.destinations=oldDestinations;BackupDocuments.factory=oldDocuments;c.deleteSharedPreferences(name);c.deleteDatabase(name+".db");assertEquals(personal,Prefs.of(c).getAll());}
    }
}
